def render_books():
    out='<div class="callout gold"><b>范围与证据：31项精选书目，持续扩充</b><p>“所有相关书籍”不是可封闭穷尽的集合。本馆区分核心教育著作、历史源流和关联比较读物。中文状态只反映本轮核实结果；“中译未核实”不等于没有中译本。参考译名不冒充正式出版书名。核验日期：2026-10-12。</p></div>'
    out+='''<div class="book-filters"><label>书名 / 作者 / 主题<input id="bookSearch" type="search" placeholder="例如：巴文克、三艺、家庭"></label><label>中文状态<select id="bookLanguage"><option value="all">全部书目</option><option value="verified">有中文资源证据</option><option value="unverified">中译尚未核实</option></select></label><button id="bookReset">清除筛选</button></div><p id="bookStatus" aria-live="polite"></p><div class="callout"><b>怎样读书目卡？</b><p>①先核对作者与版本。②用原创问题带着目的阅读。③把作者判断与经文、认信区分。④完成一个课堂行动。每项评价为本站原创评析，不是读者评分或出版社背书。</p></div>'''
    out+='<div class="learning-lab"><h3>四步读书法：让书目变成记忆</h3><p>点击一步查看操练；播放会依次高亮，不移动页面。</p><div class="learning-steps" role="group" aria-label="四步读书法"><button data-learn="0" aria-pressed="true">① 定位</button><button data-learn="1" aria-pressed="false">② 提问</button><button data-learn="2" aria-pressed="false">③ 分辨</button><button data-learn="3" aria-pressed="false">④ 复述</button></div><p id="learnText" aria-live="polite">定位：说出作者、地域、原作年和中译年。将一本书挂在时间线上，先知道它在回应谁。</p><button id="learnPlay" aria-pressed="false">▶ 播放记忆路径</button></div>'
    for cat in dict.fromkeys(b['cat'] for b in BOOKS):
        out+=f'<div class="book-category"><h3>{cat}</h3>'
        for i,b in enumerate(BOOKS):
            if b['cat']!=cat:continue
            verified=b['cn']!='中译未核实'
            out+=f'<article class="book-card" id="book-{i+1}" data-cn="{"verified" if verified else "unverified"}"><div class="book-title"><span class="book-number">{i+1:02}</span><div><span class="tag">{E(b["cn"])}</span><h4>{E(b["title"])}</h4><p class="original-title" lang="en">{E(b["original"])}</p></div></div><div class="book-columns"><div><h5>版本与出版</h5><dl><dt>作者 / 编者</dt><dd>{E(b["author"])}</dd><dt>原作年代 / 所列版本</dt><dd>{E(b["year"])}</dd></dl><p>{E(b["edition"])}</p><a class="ref" target="_blank" rel="noopener noreferrer" href="{E(b["url"])}">出版或馆藏证据 ↗</a></div><div><h5>目录证据与原创导读</h5><p class="source-note">{E(b["toc"])}</p><ol class="book-questions">'+''.join(f'<li>{E(t)}？</li>' for t in b['topics'])+'</ol></div></div>'
            out+=f'<div class="book-evaluation"><h5>阅读价值 · 改革宗辨析 · 实践</h5><p><b>值得读：</b>{E(b["value"])}</p><p><b>需要辨析：</b>{E(b["caution"])}</p><p><b>读后行动：</b>选上面一个问题，用原文证据回答；写出一条赞同、一条保留，再设计一次可观察的家庭或课堂练习。</p></div></article>'
        out+='</div>'
    return out
